{
  "overall_score": 1,
  "overall_summary": "The candidate gave a vague and incomplete answer that failed to address the specific prompt about pricing models for Figma's AI features, merely listing generic evaluation criteria without choosing a path or discussing the product context.",
  "strengths": [
    "Mentioned basic evaluation criteria like customer impact and engineering effort."
  ],
  "weaknesses": [
    {
      "tag": "no_prioritization_rationale",
      "evidence": "The candidate states that the decision depends on revenue impact but never evaluates specific options, chooses one, or explains why one pricing model should be chosen over another.",
      "fix": "State clear criteria, compare per-seat versus usage-based pricing against them, choose one model to build first, and explicitly state what you would not do and why."
    },
    {
      "tag": "no_success_metric",
      "evidence": "The candidate failed to provide any concrete success metric or way to measure the impact of the pricing transition.",
      "fix": "Define a primary metric such as ARPU, net revenue retention, or AI feature adoption rate to measure the success of the pricing model."
    },
    {
      "tag": "no_user_segmentation",
      "evidence": "The candidate did not identify or prioritize different user segments, such as enterprise teams versus individual freelancers.",
      "fix": "Segment the user base into distinct groups like power users and casual users, and explain how the pricing model impacts each segment differently."
    }
  ],
  "next_steps": [
    "Practice structuring product strategy questions by starting with problem framing and user segmentation.",
    "Always commit to a definite choice and provide explicit trade-off reasoning when comparing business models.",
    "Include specific, quantified success metrics for every strategic proposal."
  ]
}

{
  "overall_score": 1,
  "overall_summary": "The candidate's response is extremely brief, abstract, and fails to actually design a feature or address the core prompt. They mention speaking to customers and comparing solutions, but do not state any concrete feature, user segments, success metrics, or problem framing.",
  "strengths": [
    "Identified the importance of analyzing development costs versus business value."
  ],
  "weaknesses": [
    {
      "tag": "no_clear_problem_framing",
      "evidence": "The candidate immediately talks vaguely about talking with the customer without stating who the customer is, what specific food waste problem is being targeted, or defining the scope of the feature.",
      "fix": "Spend the first minute defining the problem by stating your assumptions out loud. For example: 'Before designing a food waste feature, I'll assume we are targeting busy head chefs in mid-sized restaurants who struggle with over-ordering perishable inventory.'"
    },
    {
      "tag": "empty_or_too_short",
      "evidence": "The entire answer is a single short paragraph that does not actually design any feature for restaurant managers.",
      "fix": "Expand the response by providing a structured product walkthrough covering user segmentation, specific pain points, a proposed solution, and success metrics."
    },
    {
      "tag": "no_success_metric",
      "evidence": "The candidate never defines a concrete success metric or way to measure the feature's impact on reducing food waste.",
      "fix": "Establish a primary success metric such as percentage reduction in spoiled inventory cost per month within 90 days of launch."
    }
  ],
  "next_steps": [
    "Practice using a structured product design framework such as CIRCLES or DIGS.",
    "Ensure every design question includes a specific user persona, a clearly scoped problem, and quantifiable success metrics.",
    "Dive deeper into feature ideation rather than staying at a high-level strategic discussion."
  ]
}

